begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000002301','ops@test.local');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000002301','Ops','00000000-0000-4000-8000-000000002301');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000002301','00000000-0000-4000-8000-000000002301');
insert into public.children(id,family_id,name) values('20000000-0000-4000-8000-000000002301','10000000-0000-4000-8000-000000002301','Child');
insert into public.task_templates(id,family_id,child_id,title,stars,starts_on) values('30000000-0000-4000-8000-000000002301','10000000-0000-4000-8000-000000002301','20000000-0000-4000-8000-000000002301','Task',3,current_date);
insert into public.task_completions(id,family_id,child_id,template_id,due_date,status,completed_at,client_id) values('40000000-0000-4000-8000-000000002301','10000000-0000-4000-8000-000000002301','20000000-0000-4000-8000-000000002301','30000000-0000-4000-8000-000000002301',current_date,'done','2026-11-02T09:00:00Z','70000000-0000-4000-8000-000000002301');
insert into public.entitlement_overrides(family_id,plan,reason,ends_at) values('10000000-0000-4000-8000-000000002301','pro','test',now()+interval '1 day');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000002301","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000002301","role":"parent"}}',true);
select throws_ok($$select public.review_task_once('50000000-0000-4000-8000-000000002301','40000000-0000-4000-8000-000000002301',true,'2026-11-02T08:00:00Z')$$,'P0001','submission_changed','stale submission cannot be reviewed');
select is(public.review_task_once('50000000-0000-4000-8000-000000002301','40000000-0000-4000-8000-000000002301',true,'2026-11-02T09:00:00Z')->>'status','approved','review succeeds');
select is(public.review_task_once('50000000-0000-4000-8000-000000002301','40000000-0000-4000-8000-000000002301',true,'2026-11-02T09:00:00Z')->>'status','approved','lost response retry returns original result');
select is((select sum(delta)::int from public.star_events where child_id='20000000-0000-4000-8000-000000002301'),3,'retry does not award stars twice');
select throws_ok($$select public.review_task_once('50000000-0000-4000-8000-000000002301','40000000-0000-4000-8000-000000002301',false,'2026-11-02T09:00:00Z')$$,'P0001','request_conflict','id cannot change intent');
select throws_ok($$select public.admin_ai_operations()$$,'42501','forbidden','parent cannot inspect operations');
select throws_ok($$select public.reserve_ai_operation('10000000-0000-4000-8000-000000002301',auth.uid(),'grade',repeat('a',64),gen_random_uuid())$$,'42501',null,'client cannot reserve paid operation');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select ok(public.reserve_ai_operation('10000000-0000-4000-8000-000000002301','00000000-0000-4000-8000-000000002301','grade',repeat('a',64),'60000000-0000-4000-8000-000000002301') ? 'id','server reserves one job');
select is(public.reserve_ai_operation('10000000-0000-4000-8000-000000002301','00000000-0000-4000-8000-000000002301','grade',repeat('a',64),gen_random_uuid())->>'error','generation_in_progress','duplicate request does not call provider');
select throws_ok($$select public.finish_ai_operation((select id from public.ai_operation_jobs where input_hash=repeat('a',64)),gen_random_uuid(),'{}')$$,'P0001','lease_lost','wrong lease cannot finish job');
select lives_ok($$select public.finish_ai_operation((select id from public.ai_operation_jobs where input_hash=repeat('a',64)),'60000000-0000-4000-8000-000000002301','{"output":{}}')$$,'result saved');
select ok(public.reserve_ai_operation('10000000-0000-4000-8000-000000002301','00000000-0000-4000-8000-000000002301','grade',repeat('a',64),gen_random_uuid()) ? 'cached','replay uses paid cached output');
select ok(public.reserve_ai_operation('10000000-0000-4000-8000-000000002301','00000000-0000-4000-8000-000000002301','plan',repeat('b',64),'60000000-0000-4000-8000-000000002302') ? 'id','plan starts');
select lives_ok($$select public.finish_ai_operation((select id from public.ai_operation_jobs where input_hash=repeat('b',64)),'60000000-0000-4000-8000-000000002302',null,'provider_outcome_unknown',true)$$,'unknown outcome saved');
select is(public.reserve_ai_operation('10000000-0000-4000-8000-000000002301','00000000-0000-4000-8000-000000002301','plan',repeat('b',64),gen_random_uuid())->>'error','ai_result_uncertain','uncertain paid request never auto retries');
reset role;
select * from finish();
rollback;
